export type IconName = keyof typeof bodies;

export function Icon({ name, size = 20, ...props }: { name: IconName; size?: number } & Omit<SVGProps<SVGSVGElement>, "name">) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      aria-hidden="true"
      focusable="false"
      className={`dash-icon${props.className ? " " + props.className : ""}`}
      {...props}
      dangerouslySetInnerHTML={{ __html: bodies[name] }}
    />
  );
}
